import{G as e,b as t,c as r,ae as o}from"./chunks/framework.l_MR1ur9.js";const i="/legacy/images/77447cbe0264ec0e1b1d.webp",p="/legacy/images/68d69cef608dd41ba16e.webp",l="/legacy/images/be292fe0d914907f46b2.webp",h="/legacy/images/d4c47bb55465766686ca.webp",n="/legacy/images/08f7a8ae6abd1f69060b.webp",d="/legacy/images/85a9873ed0a2f69a62c5.webp",s="/legacy/images/542c9a624655243abf11.webp",q=JSON.parse('{"title":"ChatGPT的使用","description":"","frontmatter":{"title":"ChatGPT的使用","date":"2023-11-23 17:53:18","author":"花木凋零成兰","tags":["AI","ChatGPT"],"categories":["人工智能"]},"headers":[],"relativePath":"AI/ChatGPT的使用.md","filePath":"AI/ChatGPT的使用.md","lastUpdated":1791630580000}'),c={name:"AI/ChatGPT的使用.md"};function m(b,a,P,g,u,f){return t(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1700761998000"},[...a[0]||(a[0]=[o('<h1 id="chatgpt的使用" tabindex="-1">ChatGPT的使用 <a class="header-anchor" href="#chatgpt的使用" aria-label="Permalink to &quot;ChatGPT的使用&quot;">​</a></h1><h2 id="如何对chatgpt进行提问" tabindex="-1">如何对ChatGPT进行提问 <a class="header-anchor" href="#如何对chatgpt进行提问" aria-label="Permalink to &quot;如何对ChatGPT进行提问&quot;">​</a></h2><h2 id="提问词工程-prompt-engineering" tabindex="-1">提问词工程(Prompt Engineering ) <a class="header-anchor" href="#提问词工程-prompt-engineering" aria-label="Permalink to &quot;提问词工程(Prompt Engineering )&quot;">​</a></h2><p>提示词，是指用户向AI模型提供的输入文本，用以引导AI模型生成特定类型的文本输出，这些输入可以是问题、任务描述或场景描述。</p><p>向AI询问问题，最首先的就是要把问题说清楚。</p><p>因此，我们为了让AI模型输出更准确的答案，所使用的那些提问题的技巧和方法就是提示词工程。合适的提示词，能够引导GPT模型生成有针对性且高质量的回复。</p><h2 id="常用的提示词六大类" tabindex="-1">常用的提示词六大类 <a class="header-anchor" href="#常用的提示词六大类" aria-label="Permalink to &quot;常用的提示词六大类&quot;">​</a></h2><h3 id="信息检索类prompt" tabindex="-1">信息检索类Prompt <a class="header-anchor" href="#信息检索类prompt" aria-label="Permalink to &quot;信息检索类Prompt&quot;">​</a></h3><p>向ChatGPT询问某些固有的知识，比如输入：“乔治·华盛顿是哪一年出生的？”</p><p><img src="'+i+'" alt="1700745592671" loading="lazy"></p><h3 id="文本生成类prompt" tabindex="-1">文本生成类Prompt <a class="header-anchor" href="#文本生成类prompt" aria-label="Permalink to &quot;文本生成类Prompt&quot;">​</a></h3><p>让ChatGPT根据特定要求来生成文本，比如：“我今天发烧40度，无法去上班，请向我的领导写一封请假信，要求字数在300字以内”</p><p><img src="'+p+'" alt="1700745738206" loading="lazy"></p><h3 id="机器翻译类prompt" tabindex="-1">机器翻译类Prompt <a class="header-anchor" href="#机器翻译类prompt" aria-label="Permalink to &quot;机器翻译类Prompt&quot;">​</a></h3><p>给定某种语言的内容，让ChatGPT翻译成另一种语言，比如：“请将‘the secret of a happy old age is nothing else but a decent agreement with loneliness.’从英语翻译成中文”</p><p><img src="'+l+'" alt="1700745948657" loading="lazy"></p><h3 id="创意写作类prompt" tabindex="-1">创意写作类Prompt <a class="header-anchor" href="#创意写作类prompt" aria-label="Permalink to &quot;创意写作类Prompt&quot;">​</a></h3><p>提出具有开放性的要求，让ChatGPT创作，比如：“写一个以美国南北战争为历史背景的短篇爱情小说，要求字数2000字以内。”</p><p><img src="'+h+'" alt="1700746181201" loading="lazy"></p><h3 id="文本摘要类prompt" tabindex="-1">文本摘要类Prompt <a class="header-anchor" href="#文本摘要类prompt" aria-label="Permalink to &quot;文本摘要类Prompt&quot;">​</a></h3><p>指定一篇文章，让ChatGPT提炼出文章的核心要点，比如以刚刚输出的故事文章进行提炼。</p><p><img src="'+n+'" alt="1700746323991" loading="lazy"></p><h3 id="咨询建议类prompt" tabindex="-1">咨询建议类Prompt <a class="header-anchor" href="#咨询建议类prompt" aria-label="Permalink to &quot;咨询建议类Prompt&quot;">​</a></h3><p>列举现实情况，向ChatGPT提供咨询建议，比如：“我是一个21岁的北京女大学生，我喜欢上了同班爱打篮球的男同学，我应该怎样向他表白？”</p><p><img src="'+d+'" alt="1700746486978" loading="lazy"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>想要提出好的问题，首先明确提示词的种类，然后对症下药。</p><h2 id="prompt需要包含的四大组成部分" tabindex="-1">Prompt需要包含的四大组成部分 <a class="header-anchor" href="#prompt需要包含的四大组成部分" aria-label="Permalink to &quot;Prompt需要包含的四大组成部分&quot;">​</a></h2><h3 id="任务" tabindex="-1">任务 <a class="header-anchor" href="#任务" aria-label="Permalink to &quot;任务&quot;">​</a></h3><p>即用户希望模型完成的具体工作，如回答问题、提供建议。</p><h3 id="上下文" tabindex="-1">上下文 <a class="header-anchor" href="#上下文" aria-label="Permalink to &quot;上下文&quot;">​</a></h3><p>有助于模型理解任务的背景信息，如相关领域知识、具体场景等。</p><h3 id="指令" tabindex="-1">指令 <a class="header-anchor" href="#指令" aria-label="Permalink to &quot;指令&quot;">​</a></h3><p>引导模型以特定方式完成任务的具体要求，如答案格式、回答深度等。</p><h3 id="角色" tabindex="-1">角色 <a class="header-anchor" href="#角色" aria-label="Permalink to &quot;角色&quot;">​</a></h3><p>设定模型在互动中扮演的身份，如专家、助手等。</p><h3 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h3><p>输入内容：“作为一个项目组的负责人，当你遇到项目组成员因工资待遇问题发生冲突时，请给出有效的解决办法。解决方法列举5条以上，总字数在200~300之间。”</p><p>分析：</p><ul><li>任务部分是“给出有效的解决方法”</li><li>上下文部分是“当你遇到项目组成员因工资待遇问题发生冲突时”</li><li>指令部分是“解决方法列举5条以上，总字数在200~300之间”</li><li>角色是“目组的负责人”</li></ul><p>示例结果如下：</p><p><img src="'+s+'" alt="1700747362349" loading="lazy"></p><h2 id="参考学习文章" tabindex="-1">参考学习文章 <a class="header-anchor" href="#参考学习文章" aria-label="Permalink to &quot;参考学习文章&quot;">​</a></h2><p><a href="https://xiaobot.net/p/ai666" target="_blank" rel="noreferrer">每个人的AI学习手册 (xiaobot.net)</a></p><p><a href="https://xiaobot.net/post/a7cc3cc5-d38e-4083-be22-73eef5c95795" target="_blank" rel="noreferrer">第10讲：如何更好地提问？ (xiaobot.net)</a></p>',45)])])}const x=e(c,[["render",m]]);export{q as __pageData,x as default};
